def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs:
        return 0

    times = sorted({t for start, end, _ in jobs for t in (start, end)})
    index = {t: i for i, t in enumerate(times)}
    n = len(times)

    # Min-cost flow on the time-line DAG. Sending k units from the first
    # to the last time chooses up to k overlapping jobs; job edges have
    # cost -pay, and timeline edges have cost 0.
    graph = [[] for _ in range(n)]

    def add_edge(u: int, v: int, cap: int, cost: int) -> None:
        graph[u].append([v, cap, cost, len(graph[v])])
        graph[v].append([u, 0, -cost, len(graph[u]) - 1])

    for i in range(n - 1):
        add_edge(i, i + 1, k, 0)

    for start, end, pay in jobs:
        add_edge(index[start], index[end], 1, -pay)

    total_cost = 0
    potential = [0] * n

    # Initial negative edges point forward in time, so shortest distances
    # can be computed in one DAG pass.
    for u in range(n):
        for v, cap, cost, _ in graph[u]:
            if cap and v > u and potential[v] > potential[u] + cost:
                potential[v] = potential[u] + cost

    for _ in range(k):
        dist = [float("inf")] * n
        prev_node = [-1] * n
        prev_edge = [-1] * n
        dist[0] = 0
        heap = [(0, 0)]

        while heap:
            d, u = __import__("heapq").heappop(heap)
            if d != dist[u]:
                continue
            for ei, (v, cap, cost, _) in enumerate(graph[u]):
                if cap <= 0:
                    continue
                reduced = cost + potential[u] - potential[v]
                nd = d + reduced
                if nd < dist[v]:
                    dist[v] = nd
                    prev_node[v] = u
                    prev_edge[v] = ei
                    __import__("heapq").heappush(heap, (nd, v))

        for v in range(n):
            if dist[v] < float("inf"):
                potential[v] += dist[v]

        v = n - 1
        while v != 0:
            u = prev_node[v]
            ei = prev_edge[v]
            edge = graph[u][ei]
            edge[1] -= 1
            graph[v][edge[3]][1] += 1
            total_cost += edge[2]
            v = u

    return -total_cost
